class TestVerificationOfValidInstances(unittest.TestCase):
    def test_structural_first(self) -> None:
        for path in sorted(
            (
                tests.common.TEST_DATA_DIR
                / "Json"
                / "Expected"
                / 'StructuralFirst'
            ).glob("**/*.json")
        ):
            with path.open("rt") as fid:
                jsonable = json.load(fid)

            instance = aas_jsonization.structural_first_from_jsonable(jsonable)

            errors = list(aas_verification.verify(instance))

            if len(errors) > 0:
                self.fail(
                    f"Expected no errors when verifying the instance de-serialized "
                    f"from {path}, but got {len(errors)} error(s):\n"
                    + "\n".join(
                        f"{error.path}: {error.cause}" for error in errors
                    )
                )

